```python
# views.py
from django.http import JsonResponse
from .models import SewageSample
import json

def get_samples(request):
    location = request.GET.get('location')
    start_date = request.GET.get('start_date')
    end_date = request.GET.get('end_date')
    result_min = request.GET.get('result_min')
    result_max = request.GET.get('result_max')

    samples = SewageSample.objects.all()

    if location:
        samples = samples.filter(Location=location)
    if start_date:
        samples = samples.filter(collectionDate__gte=start_date)
    if end_date:
        samples = samples.filter(collectionDate__lte=end_date)
    if result_min:
        samples = samples.filter(Result__gte=float(result_min))
    if result_max:
        samples = samples.filter(Result__lte=float(result_max))

    data = []
    for sample in samples:
        data.append({
            'SampleID': sample.SampleID,
            'Location': sample.Location,
            'collectionDate': sample.collectionDate.strftime('%Y-%m-%d'),
            'Result': sample.Result,
            'VTM': sample.VTM,
            'copies_per_L': sample.copies_per_L,
            'coordinates': sample.coordinates
        })
    return JsonResponse(data, safe=False)
```

